/**
 * Server-side helper to resolve the active studio context for the current user.
 *
 * Resolution order:
 *  1. Cookie `inkos_active_studio` (httpOnly, SameSite=Lax, Max-Age 31536000)
 *  2. First membership ordered by studio_members.created_at ASC
 *
 * URL param `?studio=X` is honoured via <StudioParamSync> client component on mount —
 * it fires a POST to /api/context/set-studio which writes the cookie, then calls
 * router.refresh(). Layout reads only cookie + fallback (no search param in layout).
 *
 * Throws if the user has no studio memberships (caller redirects to /onboarding).
 */

import { cookies } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'
import type { PlanTier } from '@/lib/billing/feature-gate'

export type StudioRow = Database['public']['Tables']['studios']['Row']
export type StudioMemberRow = Database['public']['Tables']['studio_members']['Row']
export type StudioMemberRole = StudioMemberRow['role']

export interface StudioMembership {
  studioId: string
  studio: StudioRow
  role: StudioMemberRole
  /** Resolved subscription plan for this studio. Defaults 'solo' if no active sub. */
  plan: PlanTier
}

export interface ActiveStudioContext {
  studioId: string
  studio: StudioRow
  role: StudioMemberRole
  plan: PlanTier
  allMemberships: StudioMembership[]
}

export class NoStudioMembershipError extends Error {
  constructor() {
    super('User has no studio memberships')
    this.name = 'NoStudioMembershipError'
  }
}

export async function getActiveStudio(): Promise<ActiveStudioContext> {
  const supabase = await createClient()

  // 1. Identify current user
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()
  if (authError || !user) {
    throw new NoStudioMembershipError()
  }

  // 2. Fetch all memberships with studio data, ordered by created_at ASC
  const { data: rows, error: memberError } = await supabase
    .from('studio_members')
    .select(
      `
      studio_id,
      role,
      created_at,
      studios (
        id, name, slug, timezone, locale, currency, brand_color, logo_url, plan_id,
        custom_domain, custom_domain_verified, custom_domain_verified_at,
        white_label_enabled, custom_favicon_url, custom_email_from_name,
        custom_email_reply_to, powered_by_hidden, status, created_at, updated_at
      )
      `
    )
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })

  if (memberError || !rows || rows.length === 0) {
    throw new NoStudioMembershipError()
  }

  // 3. Resolve plan for each studio (subscription lookup per studio_id)
  //    Use Promise.all with a small batch to avoid N+1 for users with many studios.
  const membershipsWithPlan: StudioMembership[] = await Promise.all(
    rows.map(async (row) => {
      // Type-safe studio extract — the join shape is deterministic
      const studio = (
        Array.isArray(row.studios) ? row.studios[0] : row.studios
      ) as StudioRow | null

      if (!studio) {
        // Edge: studio row deleted but membership exists — skip gracefully
        return null
      }

      let plan: PlanTier = 'solo'
      const { data: sub } = await supabase
        .from('subscriptions')
        .select('plan_tier')
        .eq('studio_id', row.studio_id)
        .eq('status', 'active')
        .maybeSingle()
      if (sub?.plan_tier) {
        plan = sub.plan_tier as PlanTier
      }

      return {
        studioId: row.studio_id,
        studio,
        role: row.role as StudioMemberRole,
        plan,
      } satisfies StudioMembership
    })
  )

  // Filter out any null slots (deleted studios)
  const validMemberships = membershipsWithPlan.filter(
    (m): m is StudioMembership => m !== null
  )

  if (validMemberships.length === 0) {
    throw new NoStudioMembershipError()
  }

  // 4. Resolve active studio from cookie
  const cookieStore = await cookies()
  const cookieValue = cookieStore.get('inkos_active_studio')?.value

  let resolved: StudioMembership | undefined

  if (cookieValue) {
    // Validate cookie value against actual memberships (defence-in-depth)
    resolved = validMemberships.find((m) => m.studioId === cookieValue)
    if (!resolved) {
      // Cookie holds a studio the user no longer belongs to — clear it
      // (Can't set cookies in layout Server Component; the route handler will clear it.
      //  Fall back silently here to the first membership.)
    }
  }

  // 5. Fallback to first membership
  if (!resolved) {
    resolved = validMemberships[0]
  }

  return {
    studioId: resolved.studioId,
    studio: resolved.studio,
    role: resolved.role,
    plan: resolved.plan,
    allMemberships: validMemberships,
  }
}

/**
 * Server-side helper to resolve the active location context for the current studio.
 *
 * Resolution order:
 *  1. Cookie `inkos_active_location` (httpOnly, SameSite=Lax, Max-Age 31536000)
 *  2. Studio's primary location (is_primary = true)
 *  3. First location ordered by sort_order ASC, created_at ASC
 *  4. null (all-locations view) — only returned if no locations exist
 *
 * "All locations" view (locationId = null) is only eligible for owner/admin roles.
 * Artists/receptionists/guest_artists always resolve to a specific location.
 */

import { cookies } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'
import type { StudioMemberRole } from '@/lib/context/active-studio'

export type LocationRow = Database['public']['Tables']['locations']['Row']

export interface ActiveLocationContext {
  /** null means "All locations" view — only for owner/admin */
  locationId: string | null
  location: LocationRow | null
  allLocations: LocationRow[]
}

const ALL_LOCATIONS_ROLES: StudioMemberRole[] = ['owner', 'admin']

export async function getActiveLocation(
  studioId: string,
  role: StudioMemberRole
): Promise<ActiveLocationContext> {
  const supabase = await createClient()

  // 1. Fetch all locations for this studio
  const { data: locations } = await supabase
    .from('locations')
    .select('*')
    .eq('studio_id', studioId)
    .order('sort_order', { ascending: true })
    .order('created_at', { ascending: true })

  const allLocations: LocationRow[] = locations ?? []

  if (allLocations.length === 0) {
    return { locationId: null, location: null, allLocations: [] }
  }

  // 2. Read cookie
  const cookieStore = await cookies()
  const cookieValue = cookieStore.get('inkos_active_location')?.value

  // Helper: check if role can use "All locations" view
  const canViewAll = ALL_LOCATIONS_ROLES.includes(role)

  // 3. Cookie value "null" means the user explicitly chose "All locations"
  if (cookieValue === 'null' && canViewAll) {
    return { locationId: null, location: null, allLocations }
  }

  if (cookieValue && cookieValue !== 'null') {
    // Validate location belongs to this studio
    const found = allLocations.find((l) => l.id === cookieValue)
    if (found) {
      return { locationId: found.id, location: found, allLocations }
    }
    // Cookie is stale (location deleted or studio switched) — fall through to default
  }

  // 4. Fallback: primary location first
  const primary = allLocations.find((l) => l.is_primary)
  const defaultLocation = primary ?? allLocations[0]

  if (!defaultLocation) {
    return { locationId: null, location: null, allLocations }
  }

  return {
    locationId: defaultLocation.id,
    location: defaultLocation,
    allLocations,
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { cookies } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

const SetStudioSchema = z.object({
  studioId: z.string().uuid(),
})

const COOKIE_NAME_STUDIO = 'inkos_active_studio'
const COOKIE_NAME_LOCATION = 'inkos_active_location'
const ONE_YEAR_SECONDS = 31_536_000

export async function POST(request: NextRequest) {
  const supabase = await createClient()
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()

  if (authError || !user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = SetStudioSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { studioId } = parsed.data

  // Defence-in-depth: verify the user actually belongs to this studio
  const { data: membership, error: memberError } = await supabase
    .from('studio_members')
    .select('id')
    .eq('user_id', user.id)
    .eq('studio_id', studioId)
    .is('deactivated_at', null)
    .maybeSingle()

  if (memberError) {
    logger.error({ err: memberError, userId: user.id, studioId }, 'set-studio: membership lookup failed')
    return NextResponse.json({ error: 'Internal error' }, { status: 500 })
  }

  if (!membership) {
    return NextResponse.json({ error: 'Forbidden — not a member of this studio' }, { status: 403 })
  }

  // Write cookies via NextResponse so they are set on the response
  const response = NextResponse.json({ ok: true })

  const isProduction = process.env.NODE_ENV === 'production'

  const cookieStore = await cookies()

  // Set active studio cookie
  cookieStore.set(COOKIE_NAME_STUDIO, studioId, {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
    maxAge: ONE_YEAR_SECONDS,
    secure: isProduction,
  })

  // Clear active location cookie so it re-resolves under the new studio
  cookieStore.set(COOKIE_NAME_LOCATION, '', {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
    secure: isProduction,
  })

  return response
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { cookies } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

const SetLocationSchema = z.object({
  locationId: z.string().uuid().nullable(),
})

const COOKIE_NAME_STUDIO = 'inkos_active_studio'
const COOKIE_NAME_LOCATION = 'inkos_active_location'
const ONE_YEAR_SECONDS = 31_536_000

const ALL_LOCATIONS_ROLES = new Set(['owner', 'admin'])

export async function POST(request: NextRequest) {
  const supabase = await createClient()
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()

  if (authError || !user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = SetLocationSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { locationId } = parsed.data

  // Derive studio from cookie — NEVER from request body (security: prevents cross-studio location injection)
  const cookieStore = await cookies()
  const studioIdFromCookie = cookieStore.get(COOKIE_NAME_STUDIO)?.value

  if (!studioIdFromCookie) {
    return NextResponse.json({ error: 'No active studio set' }, { status: 400 })
  }

  // Verify user membership in the cookie studio
  const { data: membership, error: memberError } = await supabase
    .from('studio_members')
    .select('role')
    .eq('user_id', user.id)
    .eq('studio_id', studioIdFromCookie)
    .is('deactivated_at', null)
    .maybeSingle()

  if (memberError) {
    logger.error({ err: memberError, userId: user.id, studioId: studioIdFromCookie }, 'set-location: membership lookup failed')
    return NextResponse.json({ error: 'Internal error' }, { status: 500 })
  }

  if (!membership) {
    return NextResponse.json({ error: 'Forbidden — not a member of this studio' }, { status: 403 })
  }

  const isProduction = process.env.NODE_ENV === 'production'

  if (locationId === null) {
    // "All locations" is only allowed for owner/admin
    if (!ALL_LOCATIONS_ROLES.has(membership.role)) {
      return NextResponse.json(
        { error: 'Forbidden — only owners and admins can view all locations' },
        { status: 403 }
      )
    }

    // Store the explicit "all locations" intent as the string "null"
    cookieStore.set(COOKIE_NAME_LOCATION, 'null', {
      httpOnly: true,
      sameSite: 'lax',
      path: '/',
      maxAge: ONE_YEAR_SECONDS,
      secure: isProduction,
    })

    return NextResponse.json({ ok: true })
  }

  // Validate location belongs to the active studio
  const { data: location, error: locationError } = await supabase
    .from('locations')
    .select('id')
    .eq('id', locationId)
    .eq('studio_id', studioIdFromCookie)
    .maybeSingle()

  if (locationError) {
    logger.error({ err: locationError, locationId, studioId: studioIdFromCookie }, 'set-location: location lookup failed')
    return NextResponse.json({ error: 'Internal error' }, { status: 500 })
  }

  if (!location) {
    return NextResponse.json(
      { error: 'Forbidden — location does not belong to active studio' },
      { status: 403 }
    )
  }

  cookieStore.set(COOKIE_NAME_LOCATION, locationId, {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
    maxAge: ONE_YEAR_SECONDS,
    secure: isProduction,
  })

  return NextResponse.json({ ok: true })
}

'use client'

/**
 * StudioParamSync — invisible client component.
 *
 * Reads ?studio=X from the URL on mount. If present and different from the
 * current active studio, fires a POST to /api/context/set-studio, then calls
 * router.refresh() so the layout re-renders with the correct studio context.
 *
 * This is how deep links from emails work (e.g. a shared calendar link that
 * includes ?studio=<uuid>). The layout cannot read search params directly
 * (only page.tsx can), so we delegate URL-param handling to this client stub.
 *
 * Renders null — zero visible UI.
 */

import { useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'

interface StudioParamSyncProps {
  currentStudioId: string
}

export function StudioParamSync({ currentStudioId }: StudioParamSyncProps) {
  const router = useRouter()
  const hasSynced = useRef(false)

  useEffect(() => {
    if (hasSynced.current) return

    const params = new URLSearchParams(window.location.search)
    const studioParam = params.get('studio')

    if (!studioParam || studioParam === currentStudioId) return

    hasSynced.current = true

    void (async () => {
      try {
        const res = await fetch('/api/context/set-studio', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ studioId: studioParam }),
        })
        if (res.ok) {
          router.refresh()
        }
      } catch {
        // Silent failure — param sync is best-effort; user can still switch manually
      }
    })()
  }, [currentStudioId, router])

  return null
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Check, ChevronsUpDown, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { cn } from '@/lib/utils'
import type { StudioMembership } from '@/lib/context/active-studio'

interface StudioSwitcherProps {
  currentStudioId: string
  allMemberships: StudioMembership[]
}

function getMonogram(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((w) => w[0] ?? '')
    .join('')
    .toUpperCase()
}

interface StudioLogoProps {
  name: string
  logoUrl: string | null
  className?: string
  monogramClassName?: string
}

function StudioLogo({ name, logoUrl, className, monogramClassName }: StudioLogoProps) {
  if (logoUrl) {
    return (
      <img
        src={logoUrl}
        alt={name}
        className={cn('rounded object-cover', className)}
        aria-hidden="true"
      />
    )
  }
  return (
    <span
      className={cn(
        'flex items-center justify-center rounded bg-primary/10 font-bold text-primary',
        monogramClassName,
        className,
      )}
      aria-hidden="true"
    >
      {getMonogram(name)}
    </span>
  )
}

export function StudioSwitcher({ currentStudioId, allMemberships }: StudioSwitcherProps) {
  const router = useRouter()
  const [pendingId, setPendingId] = useState<string | null>(null)

  const currentMembership = allMemberships.find((m) => m.studioId === currentStudioId)
  const studioName = currentMembership?.studio.name ?? 'Studio'
  const logoUrl = currentMembership?.studio.logo_url ?? null

  async function handleSwitch(studioId: string) {
    if (studioId === currentStudioId || pendingId !== null) return
    setPendingId(studioId)
    try {
      const res = await fetch('/api/context/set-studio', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ studioId }),
      })
      if (!res.ok) {
        throw new Error('Switch failed')
      }
      router.refresh()
    } catch {
      toast.error('Failed to switch studio. Try again.')
      setPendingId(null)
    }
  }

  const isSwitching = pendingId !== null

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type="button"
            aria-haspopup="listbox"
            aria-label="Switch studio"
            className={cn(
              'flex h-8 max-w-[200px] items-center gap-1.5 rounded-lg border border-border/60 bg-transparent px-2',
              'text-[13px] font-medium text-foreground transition-colors duration-100',
              'hover:bg-muted/50',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
              isSwitching && 'pointer-events-none opacity-70',
            )}
          />
        }
      >
        <StudioLogo
          name={studioName}
          logoUrl={logoUrl}
          className="h-5 w-5 shrink-0 text-[10px]"
        />
        <span className="truncate">{studioName}</span>
        <ChevronsUpDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground/50 transition-transform duration-150 data-[state=open]:rotate-180" aria-hidden="true" />
      </DropdownMenuTrigger>

      <DropdownMenuContent
        side="bottom"
        align="start"
        sideOffset={8}
        className="w-64 max-h-80 overflow-y-auto rounded-xl border-border/60 p-1.5 shadow-[var(--shadow-lift)]"
      >
        <DropdownMenuLabel className="px-2 pb-1 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground/60">
          Switch studio
        </DropdownMenuLabel>
        <DropdownMenuSeparator />

        {allMemberships.map((membership) => {
          const isActive = membership.studioId === currentStudioId
          const isPending = membership.studioId === pendingId

          return (
            <DropdownMenuItem
              key={membership.studioId}
              onClick={() => void handleSwitch(membership.studioId)}
              className="flex cursor-pointer items-center gap-2.5 rounded-md px-2 py-2 text-[13px] hover:bg-accent focus:bg-accent"
            >
              <StudioLogo
                name={membership.studio.name}
                logoUrl={membership.studio.logo_url}
                className="h-7 w-7 shrink-0 text-[10px]"
              />
              <div className="flex-1 min-w-0">
                <p className="truncate text-[13px] font-medium leading-tight">
                  {membership.studio.name}
                </p>
                <p className="text-[11px] capitalize text-muted-foreground">
                  {membership.role.replace('_', ' ')}
                </p>
              </div>
              <PlanBadge plan={membership.plan} />
              {isPending ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin text-muted-foreground" aria-hidden="true" />
              ) : (
                <Check
                  className={cn(
                    'h-4 w-4 text-primary',
                    isActive ? 'visible' : 'invisible',
                  )}
                  aria-hidden="true"
                />
              )}
            </DropdownMenuItem>
          )
        })}

        <DropdownMenuSeparator />
        {/* TODO: Wire to onboarding?new=1 when multi-studio onboarding is built */}
        <DropdownMenuItem
          onClick={() => router.push('/onboarding?new=1')}
          className="cursor-pointer rounded-md px-2 py-1.5 text-[13px] text-muted-foreground hover:bg-accent focus:bg-accent"
        >
          + New studio
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Check, ChevronDown, Loader2, MapPin } from 'lucide-react'
import { toast } from 'sonner'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { cn } from '@/lib/utils'
import type { LocationRow } from '@/lib/context/active-location'
import type { StudioMemberRole } from '@/lib/context/active-studio'

interface LocationSwitcherProps {
  currentLocationId: string | null
  allLocations: LocationRow[]
  /** Role of the current user — owner/admin can see "All locations" */
  role: StudioMemberRole
}

const ALL_LOCATIONS_ROLES: StudioMemberRole[] = ['owner', 'admin']

export function LocationSwitcher({
  currentLocationId,
  allLocations,
  role,
}: LocationSwitcherProps) {
  const router = useRouter()
  const [pending, setPending] = useState(false)

  const canViewAll = ALL_LOCATIONS_ROLES.includes(role)
  const currentLocation = allLocations.find((l) => l.id === currentLocationId)
  const triggerLabel = currentLocationId === null ? 'All locations' : (currentLocation?.name ?? 'Location')

  async function handleSwitch(locationId: string | null) {
    if (locationId === currentLocationId || pending) return
    setPending(true)
    try {
      const res = await fetch('/api/context/set-location', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ locationId }),
      })
      if (!res.ok) {
        throw new Error('Switch failed')
      }
      router.refresh()
    } catch {
      toast.error('Failed to switch location. Try again.')
      setPending(false)
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type="button"
            aria-haspopup="listbox"
            aria-label="Switch location"
            className={cn(
              'flex h-8 max-w-[180px] items-center gap-1.5 rounded-lg border border-border/60 bg-transparent px-2',
              'text-[13px] font-medium text-foreground transition-colors duration-100',
              'hover:bg-muted/50',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
              pending && 'pointer-events-none opacity-70',
            )}
          />
        }
      >
        <MapPin className="h-3.5 w-3.5 shrink-0 text-muted-foreground/60" aria-hidden="true" />
        <span className="truncate">{triggerLabel}</span>
        <ChevronDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground/50 transition-transform duration-150 data-[state=open]:rotate-180" aria-hidden="true" />
      </DropdownMenuTrigger>

      <DropdownMenuContent
        side="bottom"
        align="start"
        sideOffset={8}
        className="w-56 rounded-xl border-border/60 p-1.5 shadow-[var(--shadow-lift)]"
      >
        <DropdownMenuLabel className="px-2 pb-1 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground/60">
          Switch location
        </DropdownMenuLabel>
        <DropdownMenuSeparator />

        {canViewAll && (
          <>
            <DropdownMenuItem
              onClick={() => void handleSwitch(null)}
              className="flex cursor-pointer items-center gap-2 rounded-md px-2 py-1.5 text-[13px] hover:bg-accent focus:bg-accent"
            >
              <MapPin className="h-3.5 w-3.5 shrink-0 text-muted-foreground/60" aria-hidden="true" />
              <span className="flex-1 truncate">All locations</span>
              {pending ? (
                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" aria-hidden="true" />
              ) : (
                <Check
                  className={cn(
                    'h-4 w-4 text-primary',
                    currentLocationId === null ? 'visible' : 'invisible',
                  )}
                  aria-hidden="true"
                />
              )}
            </DropdownMenuItem>
            <DropdownMenuSeparator />
          </>
        )}

        {allLocations.map((location) => {
          const isActive = location.id === currentLocationId

          return (
            <DropdownMenuItem
              key={location.id}
              onClick={() => void handleSwitch(location.id)}
              className="flex cursor-pointer items-center gap-2 rounded-md px-2 py-1.5 text-[13px] hover:bg-accent focus:bg-accent"
            >
              <MapPin className="h-3.5 w-3.5 shrink-0 text-muted-foreground/60" aria-hidden="true" />
              <span className="flex-1 truncate">{location.name}</span>
              {pending ? (
                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" aria-hidden="true" />
              ) : (
                <Check
                  className={cn(
                    'h-4 w-4 text-primary',
                    isActive ? 'visible' : 'invisible',
                  )}
                  aria-hidden="true"
                />
              )}
            </DropdownMenuItem>
          )
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

