  children: React.ReactNode
}

// S15 cleanup (I4): removed stale entries for redirected routes
// (/consent-forms, /ai-design, /guest-artists, /artists/schedules, /waitlist,
//  /settings/*, legacy /settings flat paths)
const ROUTE_LABELS: Record<string, string> = {
  '/dashboard': 'Dashboard',
  '/calendar': 'Calendar',
  '/appointments': 'Appointments',
  '/appointments/new': 'New Appointment',
  '/clients': 'Clients',
  '/artists': 'Team',
  '/inventory': 'Inventory',
  '/commissions': 'Commissions',
  '/payroll': 'Payroll',
  '/payments': 'Payments',
  '/locations': 'Locations',
  '/marketing': 'Campaigns',
  '/reports': 'Reports',
  '/settings': 'Settings',
  '/settings/studio/profile': 'Studio Profile',
  '/settings/studio/branding': 'Branding',
  '/settings/studio/services': 'Services',
  '/settings/studio/policies': 'Booking Policies',
  '/settings/studio/booking-page': 'Booking Page',
  '/settings/studio/ink-registry': 'Ink Registry',
  '/settings/team/members': 'Team & Members',
  '/settings/subscription/billing': 'Billing & Plan',
  '/settings/subscription/usage': 'Usage',
  '/settings/integrations': 'Integrations',
  '/settings/account/profile': 'My Profile',
  '/settings/account/advanced': 'Advanced',
  '/admin': 'Admin',
}

function getPageLabel(pathname: string): string {
  if (ROUTE_LABELS[pathname]) return ROUTE_LABELS[pathname]
  const match = Object.keys(ROUTE_LABELS)
    .filter((k) => pathname.startsWith(k) && k !== '/')
    .sort((a, b) => b.length - a.length)[0]
  return ROUTE_LABELS[match ?? ''] ?? 'InkOS'
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((n) => n[0])
    .join('')
    .toUpperCase()
}

const G_CHORD_TIMEOUT_MS = 500

// S15 cleanup (I4): removed broken `n` chord (/consent-forms → now at /clients?tab=consent-forms)
// and `w` chord (/waitlist → now at /appointments?tab=waitlist).
// `s` chord updated to the canonical settings entry point.
const G_CHORD_MAP: Record<string, string> = {
  d: '/dashboard',
  c: '/calendar',
  l: '/clients',
  a: '/artists',
  s: '/settings/studio/profile',
  p: '/payroll',
  b: '/settings/subscription/billing',
  i: '/inventory',
}

export function AppHeader({
  studioName,
  userName,
