                <AvatarFallback className="rounded-full bg-gradient-to-br from-primary/20 to-primary/10 text-[11px] font-semibold text-primary">
                  {getInitials(userName)}
                </AvatarFallback>
              </Avatar>
              <ChevronDown className="h-3.5 w-3.5 text-muted-foreground/50 transition-transform data-[popup-open]:rotate-180" />
            </DropdownMenuTrigger>

            <DropdownMenuContent
              side="bottom"
              align="end"
              className="w-56 rounded-xl border-border/60 p-1.5 shadow-[var(--shadow-lift)]"
              sideOffset={8}
            >
              <DropdownMenuLabel className="flex items-center gap-2.5 rounded-md px-2 py-2">
                <Avatar className="h-9 w-9 rounded-full ring-1 ring-border/60">
                  {userAvatarUrl && (
                    <AvatarImage src={userAvatarUrl} alt={userName} />
                  )}
                  <AvatarFallback className="rounded-full bg-gradient-to-br from-primary/20 to-primary/10 text-[11px] font-semibold text-primary">
                    {getInitials(userName)}
                  </AvatarFallback>
                </Avatar>
                <div className="grid min-w-0 flex-1">
                  <span className="truncate text-[13px] font-semibold leading-tight">
