                      Light
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => setTheme('dark')}
                      className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]"
                    >
                      <Moon className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
