                <LogOut className="h-4 w-4" aria-hidden="true" />
                Sign out
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>

      <CommandPalette
        open={paletteOpen}
        onOpenChange={setPaletteOpen}
        onCreateClient={() => setAddClientOpen(true)}
      />
      <QuickAddClientModal open={addClientOpen} onOpenChange={setAddClientOpen} />

