import type { StudioMembership } from '@/lib/context/active-studio'
import type { LocationRow } from '@/lib/context/active-location'

interface AppHeaderProps {
  studioName: string
  userName: string
  userEmail?: string
  userAvatarUrl?: string | null
  role: NavRole
  plan?: PlanTier
  /** S15: all studio memberships — single item = no switcher rendered */
  allMemberships: StudioMembership[]
  /** S15: active studio id */
  currentStudioId: string
  /** S15: active location id (null = all locations) */
  currentLocationId: string | null
  /** S15: all locations for active studio — <2 = no switcher rendered */
  allLocations: LocationRow[]
  permissionKeys: string[]
  children: React.ReactNode
}

// S15 cleanup (I4): removed stale entries for redirected routes
// (/consent-forms, /ai-design, /guest-artists, /artists/schedules, /waitlist,
//  legacy flat /settings/* paths from pre-S14)
const ROUTE_LABELS: Record<string, string> = {
  '/dashboard': 'Dashboard',
  '/calendar': 'Calendar',
  '/appointments': 'Appointments',
  '/appointments/new': 'New Appointment',
  '/clients': 'Clients',
  '/artists': 'Team',
  '/inventory': 'Inventory',
  '/commissions': 'Commissions',
  '/payroll': 'Payroll',
  '/payments': 'Payments',
  '/locations': 'Locations',
  '/marketing': 'Campaigns',
  '/reports': 'Reports',
  '/settings': 'Settings',
  '/settings/studio/profile': 'Studio Profile',
  '/settings/studio/branding': 'Branding',
  '/settings/studio/services': 'Services',
  '/settings/studio/policies': 'Booking Policies',
  '/settings/studio/booking-page': 'Booking Page',
  '/settings/studio/ink-registry': 'Ink Registry',
  '/settings/team/members': 'Team & Members',
  '/settings/subscription/billing': 'Billing & Plan',
  '/settings/subscription/usage': 'Usage',
  '/settings/integrations': 'Integrations',
  '/settings/account/profile': 'My Profile',
  '/settings/account/advanced': 'Advanced',
  '/admin': 'Admin',
}

function getPageLabel(pathname: string): string {
  if (ROUTE_LABELS[pathname]) return ROUTE_LABELS[pathname]
  const match = Object.keys(ROUTE_LABELS)
    .filter((k) => pathname.startsWith(k) && k !== '/')
    .sort((a, b) => b.length - a.length)[0]
  return ROUTE_LABELS[match ?? ''] ?? 'InkOS'
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((n) => n[0])
    .join('')
    .toUpperCase()
}

const G_CHORD_TIMEOUT_MS = 500

// S15 cleanup (I4): removed broken `n` (/consent-forms) and `w` (/waitlist) chords
// — those routes now 307-redirect; updated `s` and `b` to S14 canonical paths
const G_CHORD_MAP: Record<string, string> = {
  d: '/dashboard',
  c: '/calendar',
  l: '/clients',
  a: '/artists',
  s: '/settings/studio/profile',
  p: '/payroll',
  b: '/settings/subscription/billing',
  i: '/inventory',
}

export function AppHeader({
  studioName,
  userName,
  userEmail,
  userAvatarUrl,
  role,
  plan = 'solo',
  allMemberships,
  currentStudioId,
  currentLocationId,
  allLocations,
  permissionKeys,
  children,
}: AppHeaderProps) {
  const pathname = usePathname()
  const router = useRouter()
  const queryClient = useQueryClient()

  // A11y: move focus to <main> on every client-side navigation (WCAG 2.4.3)
  useFocusOnRouteChange()
  const { resolvedTheme, setTheme } = useTheme()
  const supabase = createClient()

  const [paletteOpen, setPaletteOpen] = useState(false)
  const [addClientOpen, setAddClientOpen] = useState(false)
  const [newAppointmentOpen, setNewAppointmentOpen] = useState(false)
  const [mobileNavOpen, setMobileNavOpen] = useState(false)

  const lastKeyRef = useRef<string>('')
  const lastKeyTimeRef = useRef<number>(0)

  const pageLabel = getPageLabel(pathname)

  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setPaletteOpen(true)
        return
      }
      if ((e.metaKey || e.ctrlKey) && e.shiftKey && e.key === 'l') {
        e.preventDefault()
        setTheme(resolvedTheme === 'dark' ? 'light' : 'dark')
        return
      }
      if (e.metaKey || e.ctrlKey || e.altKey) return
      const target = e.target as HTMLElement
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return
      if (target.isContentEditable) return

      const key = e.key.toLowerCase()
      const now = Date.now()

      if (
        lastKeyRef.current === 'g' &&
        now - lastKeyTimeRef.current < G_CHORD_TIMEOUT_MS &&
        G_CHORD_MAP[key]
      ) {
        e.preventDefault()
        router.push(G_CHORD_MAP[key])
        lastKeyRef.current = ''
        return
      }

      // N → new booking
      if (key === 'n') {
        router.push('/appointments/new')
      }

      lastKeyRef.current = key
      lastKeyTimeRef.current = now
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [router, resolvedTheme, setTheme])

  async function handleSignOut() {
    await supabase.auth.signOut()
    router.push('/login')
    router.refresh()
  }

  return (
    <SidebarInset className="flex flex-col">
      {/* Header bar */}
      <header className="sticky top-0 z-40 flex h-14 shrink-0 items-center gap-3 border-b border-border/60 bg-background/80 px-4 backdrop-blur-md supports-[backdrop-filter]:bg-background/70">
        {/* Left */}
        <div className="flex min-w-0 flex-1 items-center gap-2">
          {/* Mobile hamburger — visible only below md */}
          <MobileNav
            userName={userName}
            userEmail={userEmail ?? ''}
            userAvatarUrl={userAvatarUrl}
            studioName={studioName}
            role={role}
            plan={plan}
            locationCount={allLocations.length}
            permissionKeys={permissionKeys}
            onSignOut={handleSignOut}
            open={mobileNavOpen}
            onOpenChange={setMobileNavOpen}
            allMemberships={allMemberships}
            currentStudioId={currentStudioId}
            currentLocationId={currentLocationId}
            allLocations={allLocations}
          />
          {/* Desktop sidebar trigger — hidden on mobile */}
          <SidebarTrigger className="hidden h-8 w-8 shrink-0 text-muted-foreground/70 hover:text-foreground md:flex" />
          <Separator orientation="vertical" className="h-4 bg-border/50" />

          {/* S15: Breadcrumb with context switchers */}
          <Breadcrumb className="min-w-0">
            <BreadcrumbList className="gap-1.5 text-[13px]">
              {/* Studio — switcher (multi-studio) or plain link (single) */}
              <BreadcrumbItem className="hidden md:flex">
                {allMemberships.length >= 2 ? (
                  <StudioSwitcher
                    currentStudioId={currentStudioId}
                    allMemberships={allMemberships}
                  />
                ) : (
                  <BreadcrumbLink
                    href="/dashboard"
                    className="truncate text-muted-foreground/80 transition-colors hover:text-foreground"
                  >
                    {studioName}
                  </BreadcrumbLink>
                )}
              </BreadcrumbItem>

              {/* Location switcher — only when >= 2 locations */}
              {allLocations.length >= 2 && (
                <>
                  <BreadcrumbSeparator className="hidden md:flex">
                    <ChevronRight className="h-3.5 w-3.5 text-muted-foreground/40" aria-hidden="true" />
                  </BreadcrumbSeparator>
                  <BreadcrumbItem className="hidden md:flex">
                    <LocationSwitcher
                      currentLocationId={currentLocationId}
                      allLocations={allLocations}
                      role={role}
                    />
                  </BreadcrumbItem>
                </>
              )}

              {/* Page label — right-most crumb, truncates first */}
              {pathname !== '/dashboard' && (
                <>
                  <BreadcrumbSeparator className="hidden md:flex">
                    <ChevronRight className="h-3.5 w-3.5 text-muted-foreground/40" aria-hidden="true" />
                  </BreadcrumbSeparator>
                  <BreadcrumbItem className="hidden md:flex">
                    <BreadcrumbPage className="truncate font-semibold tracking-tight text-foreground">
                      {pageLabel}
                    </BreadcrumbPage>
                  </BreadcrumbItem>
                </>
              )}

              {/* Mobile: show current page label only (switchers are in MobileNav sheet) */}
              <BreadcrumbItem className="flex md:hidden">
                <BreadcrumbPage className="truncate font-semibold text-foreground">
                  {pathname === '/dashboard' ? studioName : pageLabel}
                </BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>

          {/* A11y: live region for screen reader announcements on studio/location switch */}
          <div
            aria-live="polite"
            aria-atomic="true"
            className="sr-only"
            id="studio-switch-announcement"
          />
        </div>

        {/* Right */}
        <div className="flex shrink-0 items-center gap-1.5">
          {/* Mobile search trigger — visible below md */}
          <Button
            variant="ghost"
            className="flex h-11 w-11 items-center justify-center md:hidden"
            aria-label="Search"
            onClick={() => setPaletteOpen(true)}
          >
            <Search className="size-4" aria-hidden="true" />
          </Button>

          {/* Desktop Cmd+K pill — hidden on mobile */}
          <button
            type="button"
            aria-label="Open command palette"
            onClick={() => setPaletteOpen(true)}
            className="hidden h-8 cursor-pointer items-center gap-2 rounded-lg border border-border/60 bg-muted/30 px-2.5 text-[12px] font-medium text-muted-foreground/80 transition-all hover:border-border hover:bg-muted/60 hover:text-foreground md:flex"
          >
            <span>Search</span>
            <kbd className="pointer-events-none flex h-5 items-center gap-0.5 rounded border border-border/60 bg-background px-1.5 text-[10px] font-mono text-muted-foreground/60">
              <span>⌘</span><span>K</span>
            </kbd>
          </button>

          <ThemeToggle variant="icon" />

          {/* User avatar dropdown */}
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <button
                  type="button"
                  aria-label="User menu"
                  className="flex h-9 cursor-pointer items-center gap-1.5 rounded-lg px-1 text-sm outline-none transition-all hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring"
                />
              }
            >
              <Avatar className="h-7 w-7 rounded-full ring-1 ring-border/60">
                {userAvatarUrl && (
                  <AvatarImage src={userAvatarUrl} alt={userName} />
                )}
                <AvatarFallback className="rounded-full bg-gradient-to-br from-primary/20 to-primary/10 text-[11px] font-semibold text-primary">
                  {getInitials(userName)}
                </AvatarFallback>
              </Avatar>
              <ChevronDown className="h-3.5 w-3.5 text-muted-foreground/50 transition-transform data-[popup-open]:rotate-180" />
            </DropdownMenuTrigger>

            <DropdownMenuContent
              side="bottom"
              align="end"
              className="w-56 rounded-xl border-border/60 p-1.5 shadow-[var(--shadow-lift)]"
              sideOffset={8}
            >
              <DropdownMenuLabel className="flex items-center gap-2.5 rounded-md px-2 py-2">
                <Avatar className="h-9 w-9 rounded-full ring-1 ring-border/60">
                  {userAvatarUrl && (
                    <AvatarImage src={userAvatarUrl} alt={userName} />
                  )}
                  <AvatarFallback className="rounded-full bg-gradient-to-br from-primary/20 to-primary/10 text-[11px] font-semibold text-primary">
                    {getInitials(userName)}
                  </AvatarFallback>
                </Avatar>
                <div className="grid min-w-0 flex-1">
                  <span className="truncate text-[13px] font-semibold leading-tight">
                    {userName}
                  </span>
                  <span className="truncate text-[11px] font-normal text-muted-foreground">
                    {userEmail}
                  </span>
                </div>
              </DropdownMenuLabel>
              <DropdownMenuSeparator className="my-1" />

              <DropdownMenuItem
                onClick={() => router.push('/settings/account/profile')}
                className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]"
              >
                <User className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                Profile
              </DropdownMenuItem>

              <DropdownMenuItem
                onClick={() => router.push('/settings')}
                className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]"
              >
                <Settings className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                Settings
              </DropdownMenuItem>

              <DropdownMenuSub>
                <DropdownMenuSubTrigger className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]">
                  <Palette className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                  Theme
                </DropdownMenuSubTrigger>
                <DropdownMenuPortal>
                  <DropdownMenuSubContent className="rounded-xl border-border/60 p-1.5 shadow-[var(--shadow-lift)]">
                    <DropdownMenuItem
                      onClick={() => setTheme('light')}
                      className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]"
                    >
                      <Sun className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                      Light
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => setTheme('dark')}
                      className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]"
                    >
                      <Moon className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                      Dark
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => setTheme('system')}
                      className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]"
                    >
                      <SunMoon className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                      System
                    </DropdownMenuItem>
                  </DropdownMenuSubContent>
                </DropdownMenuPortal>
              </DropdownMenuSub>

              <DropdownMenuSeparator className="my-1" />

              <DropdownMenuItem
                onClick={handleSignOut}
                className="gap-2.5 rounded-md px-2 py-1.5 text-[13px] text-destructive focus:bg-destructive/10 focus:text-destructive"
              >
                <LogOut className="h-4 w-4" aria-hidden="true" />
                Sign out
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>

      <CommandPalette
        open={paletteOpen}
        onOpenChange={setPaletteOpen}
        onCreateClient={() => setAddClientOpen(true)}
      />
      <QuickAddClientModal open={addClientOpen} onOpenChange={setAddClientOpen} />

      {/* Page content */}
      <main
        id="main-content"
        tabIndex={-1}
        className="flex-1 overflow-auto bg-[var(--color-page-bg,var(--color-background))] pb-16 outline-none md:pb-0"
      >
        {children}
      </main>

      <BottomNav
        onNew={() => setNewAppointmentOpen(true)}
        onMoreOpen={() => setMobileNavOpen(true)}
      />

      <AppointmentCreateDrawer
        open={newAppointmentOpen}
        onOpenChange={setNewAppointmentOpen}
        editingId={null}
        onSuccess={() => {
          setNewAppointmentOpen(false)
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
        }}
      />
    </SidebarInset>
  )
}

'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'
import { usePathname, useRouter } from 'next/navigation'
import { LogOut, Menu, X } from 'lucide-react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Sheet, SheetContent } from '@/components/ui/sheet'
import { cn } from '@/lib/utils'
import { APP_NAV, type NavItem, type NavRole } from '@/components/app/sidebar/nav-config'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { StudioSwitcher } from '@/components/shared/StudioSwitcher'
import { LocationSwitcher } from '@/components/shared/LocationSwitcher'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { StudioMembership } from '@/lib/context/active-studio'
import type { LocationRow } from '@/lib/context/active-location'

interface MobileNavProps {
  userName: string
  userEmail: string
  userAvatarUrl: string | null | undefined
  studioName: string
  role: NavRole
  locationCount: number
  permissionKeys: string[]
  plan?: PlanTier
  onSignOut: () => void
  /** Optional external controlled open state — used by BottomNav "More" button */
  open?: boolean
  onOpenChange?: (open: boolean) => void
  /** S15: studio switcher context */
  allMemberships: StudioMembership[]
  currentStudioId: string
  /** S15: location switcher context */
  currentLocationId: string | null
  allLocations: LocationRow[]
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((n) => n[0])
    .join('')
    .toUpperCase()
}

interface MobileNavItemProps {
  item: NavItem
  onNavigate: () => void
  isActive: boolean
  plan: PlanTier
}

function MobileNavItem({ item, onNavigate, isActive, plan }: MobileNavItemProps) {
  const Icon = item.icon
  const router = useRouter()

  const isGated =
    !!item.requiredPlan &&
    !hasFeature(plan, item.featureKey ?? item.requiredPlan)

  function handleClick() {
    if (isGated) {
      onNavigate()
      router.push('/settings/subscription/billing')
      return
    }
    onNavigate()
    router.push(item.href)
  }

  return (
    <button
      type="button"
      className={cn(
        'flex w-full min-h-[44px] items-center gap-2.5 rounded-lg px-2.5 text-[13px] font-medium transition-colors text-left',
        isActive
          ? 'bg-accent text-accent-foreground'
          : 'text-muted-foreground hover:bg-muted/50 hover:text-foreground',
        isGated && 'opacity-60',
      )}
      onClick={handleClick}
      aria-current={isActive ? 'page' : undefined}
    >
      <Icon className="size-4 shrink-0" aria-hidden="true" />
      {item.label}
      {isGated && item.requiredPlan && item.requiredPlan !== 'solo' && (
        <PlanBadge plan={item.requiredPlan} className="ml-auto" />
      )}
      {item.badge && !isGated && (
        <span className="ml-auto rounded-full bg-primary/15 px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wide text-primary">
          {item.badge}
        </span>
      )}
    </button>
  )
}

/**
 * Mobile hamburger navigation. Renders a Sheet side="left" with user info,
 * S15 studio/location switchers in the sheet header, nav groups, and sign-out.
 * Auto-closes on route change.
 */
export function MobileNav({
  userName,
  userEmail,
  userAvatarUrl,
  studioName,
  role,
  locationCount,
  permissionKeys,
  plan = 'solo',
  onSignOut,
  open: externalOpen,
  onOpenChange: externalOnOpenChange,
  allMemberships,
  currentStudioId,
  currentLocationId,
  allLocations,
}: MobileNavProps) {
  const [internalOpen, setInternalOpen] = useState(false)
  const open = externalOpen !== undefined ? externalOpen : internalOpen
  const setOpen = useCallback((v: boolean) => {
    setInternalOpen(v)
    externalOnOpenChange?.(v)
  }, [externalOnOpenChange])
  const pathname = usePathname()

  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])
  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))
      .filter((group) => group.items.length > 0)
  }, [role, locationCount, permissions])

  useEffect(() => {
    setOpen(false)
  }, [pathname, setOpen])

  const showStudioSwitcher = allMemberships.length >= 2
  const showLocationSwitcher = allLocations.length >= 2

  return (
    <>
      {/* Hamburger trigger — visible only below md */}
      <Button
        variant="ghost"
        className="flex h-11 w-11 items-center justify-center md:hidden"
        aria-label="Open navigation"
        aria-expanded={open}
        aria-controls="mobile-nav-sheet"
        onClick={() => setOpen(true)}
      >
        <Menu className="size-4" aria-hidden="true" />
      </Button>

      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent
          id="mobile-nav-sheet"
          side="left"
          className="w-[280px] p-0 flex flex-col"
          showCloseButton={false}
        >
          {/* User header */}
          <div className="flex items-center gap-3 border-b border-border/60 px-4 py-4">
            <Avatar className="h-9 w-9 rounded-full ring-1 ring-border/60 shrink-0">
              {userAvatarUrl && <AvatarImage src={userAvatarUrl} alt={userName} />}
              <AvatarFallback className="rounded-full bg-gradient-to-br from-primary/20 to-primary/10 text-[11px] font-semibold text-primary">
                {getInitials(userName)}
              </AvatarFallback>
            </Avatar>
            <div className="min-w-0 flex-1">
              <p className="truncate text-[13px] font-semibold leading-tight text-foreground">
                {userName}
              </p>
              <p className="truncate text-[11px] text-muted-foreground">{studioName}</p>
              <p className="truncate text-[10px] text-muted-foreground/60">{userEmail}</p>
            </div>
            <Button
              variant="ghost"
              className="h-8 w-8 shrink-0"
              onClick={() => setOpen(false)}
              aria-label="Close navigation"
            >
              <X className="size-4" aria-hidden="true" />
            </Button>
          </div>

          {/* S15: Context switchers — shown in mobile sheet between user header and nav groups */}
          {(showStudioSwitcher || showLocationSwitcher) && (
            <div className="border-b border-border/60 px-3 py-2 space-y-1">
              {showStudioSwitcher && (
                <div className="flex items-center gap-2 min-h-[44px] px-1">
                  <span className="w-16 shrink-0 text-[11px] text-muted-foreground/60">Studio</span>
                  <StudioSwitcher
                    currentStudioId={currentStudioId}
                    allMemberships={allMemberships}
                  />
                </div>
              )}
              {showLocationSwitcher && (
                <div className="flex items-center gap-2 min-h-[44px] px-1">
                  <span className="w-16 shrink-0 text-[11px] text-muted-foreground/60">Location</span>
                  <LocationSwitcher
                    currentLocationId={currentLocationId}
                    allLocations={allLocations}
                    role={role}
                  />
                </div>
              )}
            </div>
          )}

          {/* Scrollable nav groups */}
          <ScrollArea className="flex-1">
            <nav className="px-2 py-3 space-y-4" aria-label="Mobile navigation">
              {navGroups.map((group) => (
                <div key={group.label}>
                  <p className="mb-1 px-2 text-[10px] font-semibold uppercase tracking-[0.1em] text-muted-foreground/50">
                    {group.label}
                  </p>
                  <div className="space-y-0.5">
                    {group.items.map((item) => (
                      <MobileNavItem
                        key={item.href}
                        item={item}
                        isActive={
                          item.href === '/dashboard'
                            ? pathname === item.href
                            : pathname.startsWith(item.href.split('?')[0] ?? item.href)
                        }
                        onNavigate={() => setOpen(false)}
                        plan={plan}
                      />
                    ))}
                  </div>
                </div>
              ))}
            </nav>
          </ScrollArea>

          {/* Sign out footer */}
          <div className="border-t border-border/60 p-3 safe-bottom">
            <Button
              variant="ghost"
              className="w-full justify-start gap-2.5 text-[13px] text-destructive hover:bg-destructive/10 hover:text-destructive"
              onClick={() => {
                setOpen(false)
                onSignOut()
              }}
            >
              <LogOut className="size-4" aria-hidden="true" />
              Sign out
            </Button>
          </div>
        </SheetContent>
      </Sheet>
    </>
  )
}

